class Colormap:
    def __init__(self, name="custom", N=256):
        self.name, self.N = name, N

    def __call__(self, x, alpha=None, bytes=False):
        import numpy as np
        scalar = isinstance(x, (int, float))
        xs = [float(x)] if scalar else [float(v) for v in np.asarray(x).ravel().tolist()]
