def nanmedian(a, axis=None, out=None, overwrite_input=False, keepdims=False):
    a = asarray(a)
    if axis is None:
        a = a.ravel()
        return median(a[~isnan(a)])
    return apply_along_axis(lambda r: median(r[~isnan(r)]), axis, a)


def quantile(a, q, axis=None, out=None, overwrite_input=False, method="linear", keepdims=False):
    a = asarray(a)
    if axis is None:
        a, axis = a.ravel(), 0
    s = moveaxis(sort(a, axis=axis), axis, -1)
    n = s.shape[-1]
    qs = asarray(q, float64)
    vals = []
    for qq in qs.ravel().tolist():
        if not (0 <= qq <= 1):
            raise ValueError("Quantiles must be in the range [0, 1]")
        virtual = (n - 1) * qq
        if method in ("lower", "higher", "nearest"):
            k = {"lower": _math.floor, "higher": _math.ceil, "nearest": _builtins.round}[method](virtual)
            vals.append(s[..., int(k)])
            continue
        lo = int(_math.floor(virtual))
        hi = _builtins.min(lo + 1, n - 1)
        if method == "midpoint":
            vals.append((asarray(s[..., lo], float64) + s[..., hi]) / 2)
            continue
        t = virtual - lo
        av, bv = asarray(s[..., lo], float64), asarray(s[..., hi], float64)
        diff_b_a = bv - av
        vals.append(where(t >= 0.5, bv - diff_b_a * (1 - t), av + diff_b_a * t))  # NumPy's _lerp
    res = array(vals) if qs.ndim else asarray(vals[0])
    if qs.ndim:
        res = res.reshape(qs.shape + res.shape[1:])
    if keepdims:
        res = expand_dims(res, axis if qs.ndim == 0 else axis + qs.ndim)
    return res if res.ndim else res[()]


def percentile(a, q, axis=None, out=None, overwrite_input=False, method="linear", keepdims=False):
    return quantile(a, asarray(q, float64) / 100, axis=axis, method=method, keepdims=keepdims)


def average(a, axis=None, weights=None, returned=False, *, keepdims=False):
    a = asarray(a)
    if weights is None:
        avg = mean(a, axis, keepdims=keepdims)
        scl = float64(_count(a, axis))
    else:
        w = asarray(weights)
        if w.shape != a.shape and axis is not None:
            s = [1] * a.ndim
            s[axis] = w.shape[0]
            w = w.reshape(s)
        scl = sum(broadcast_to(w, a.shape) * 1.0, axis, keepdims=keepdims)
        avg = sum(a * w, axis, keepdims=keepdims) / scl
    return (avg, scl) if returned else avg


def cov(m, y=None, rowvar=True, bias=False, ddof=None):
    X = atleast_2d(asarray(m, float64))
    if not rowvar and X.shape[0] != 1:
        X = X.T
    if y is not None:
        y = atleast_2d(asarray(y, float64))
        if not rowvar and y.shape[0] != 1:
            y = y.T
        X = concatenate((X, y), axis=0)
    if ddof is None:
        ddof = 0 if bias else 1
    n = X.shape[1]
    X = X - mean(X, axis=1, keepdims=True)
    c = X @ X.T.conj() / (n - ddof)
    return c.squeeze() if c.size == 1 else c


def corrcoef(x, y=None, rowvar=True):
    c = cov(x, y, rowvar)
    if asarray(c).ndim == 0:
        return c / c
    d = sqrt(diag(c))
    c = c / d[:, None]
    c = c / d[None, :]
    return clip(c, -1, 1)


# ------------------------------------------------------------------ shapes

def shape(a):
    return asarray(a).shape


def ndim(a):
    return asarray(a).ndim


def size(a, axis=None):
    a = asarray(a)
    return a.size if axis is None else a.shape[axis]


def reshape(a, shape=None, order="C", *, newshape=None, copy=None):
    return _np.reshape(asarray(a), _shape(shape if shape is not None else newshape))


def ravel(a, order="C"):
    return _np.ravel(asarray(a))


def transpose(a, axes=None):
    return _np.transpose(asarray(a), axes)


def swapaxes(a, axis1, axis2):
    return asarray(a).swapaxes(axis1, axis2)


def moveaxis(a, source, destination):
    a = asarray(a)
    src = [s % a.ndim for s in (source if isinstance(source, (tuple, list)) else [source])]
    dst = [d % a.ndim for d in (destination if isinstance(destination, (tuple, list)) else [destination])]
    order = [i for i in range(a.ndim) if i not in src]
    for d, s in sorted(zip(dst, src)):
        order.insert(d, s)
    return _np.transpose(a, order)


def squeeze(a, axis=None):
    a = asarray(a)
    if axis is None:
        return a.reshape(tuple(n for n in a.shape if n != 1))
    axes = [x % a.ndim for x in (axis if isinstance(axis, (tuple, list)) else [axis])]
    for x in axes:
        if a.shape[x] != 1:
            raise ValueError("cannot select an axis to squeeze out which has size not equal to one")
    return a.reshape(tuple(n for i, n in enumerate(a.shape) if i not in axes))


def expand_dims(a, axis):
    a = asarray(a)
    axes = axis if isinstance(axis, (tuple, list)) else [axis]
    nd = a.ndim + len(axes)
    shape = list(a.shape)
    for x in sorted(x % nd for x in axes):
        shape.insert(x, 1)
    return a.reshape(shape)


def atleast_1d(*arys):
    res = [asarray(a) if asarray(a).ndim >= 1 else asarray(a).reshape(1) for a in arys]
    return res[0] if len(res) == 1 else res


def atleast_2d(*arys):
    res = []
    for a in arys:
        a = asarray(a)
        res.append(a.reshape(1, 1) if a.ndim == 0 else a.reshape(1, -1) if a.ndim == 1 else a)
    return res[0] if len(res) == 1 else res


def atleast_3d(*arys):
    res = []
    for a in arys:
        a = asarray(a)
        if a.ndim == 0:
            a = a.reshape(1, 1, 1)
        elif a.ndim == 1:
            a = a.reshape(1, -1, 1)
        elif a.ndim == 2:
            a = a.reshape(a.shape + (1,))
        res.append(a)
    return res[0] if len(res) == 1 else res


def concatenate(arrays, axis=0, out=None, dtype=None):
    r = _np.concatenate([asarray(a) for a in arrays], axis)
    if dtype is not None:
        r = r.astype(dtype)
    return _out(r, out)


concat = concatenate


def stack(arrays, axis=0, out=None):
    arrs = [asarray(a) for a in arrays]
    if not arrs:
        raise ValueError("need at least one array to stack")
    for a in arrs:
        if a.shape != arrs[0].shape:
            raise ValueError("all input arrays must have the same shape")
    ax = axis % (arrs[0].ndim + 1)
    return concatenate([expand_dims(a, ax) for a in arrs], axis=ax)


def vstack(tup, *, dtype=None):
    return concatenate([atleast_2d(a) for a in tup], axis=0, dtype=dtype)


row_stack = _removed_alias(vstack, "row_stack", "np.vstack")


def hstack(tup, *, dtype=None):
    arrs = [atleast_1d(a) for a in tup]
    return concatenate(arrs, axis=0 if arrs[0].ndim == 1 else 1, dtype=dtype)


def dstack(tup):
    return concatenate([atleast_3d(a) for a in tup], axis=2)


def column_stack(tup):
    arrs = []
    for a in tup:
        a = asarray(a)
        arrs.append(a.reshape(-1, 1) if a.ndim < 2 else a)
    return concatenate(arrs, axis=1)


def array_split(ary, indices_or_sections, axis=0):
    a = asarray(ary)
    n = a.shape[axis]
    if isinstance(indices_or_sections, int):
        k = indices_or_sections
        each, extra = divmod(n, k)
        bounds = [0]
        for i in range(k):
            bounds.append(bounds[-1] + each + (1 if i < extra else 0))
    else:
        bounds = [0] + list(indices_or_sections) + [n]
    res = []
    for lo, hi in zip(bounds[:-1], bounds[1:]):
        idx = [slice(None)] * a.ndim
        idx[axis] = slice(lo, hi)
        res.append(a[tuple(idx)])
    return res


def split(ary, indices_or_sections, axis=0):
    if isinstance(indices_or_sections, int) and asarray(ary).shape[axis] % indices_or_sections:
        raise ValueError("array split does not result in an equal division")
    return array_split(ary, indices_or_sections, axis)


def hsplit(ary, n):
    return split(ary, n, axis=1 if asarray(ary).ndim > 1 else 0)


def vsplit(ary, n):
    return split(ary, n, axis=0)


def take(a, indices, axis=None):
    a = asarray(a)
    if axis is None:
        return a.ravel()[asarray(indices)]
    idx = [slice(None)] * a.ndim
    idx[axis] = asarray(indices)
    return a[tuple(idx)]


def repeat(a, repeats, axis=None):
    a = asarray(a)
    if axis is None:
        a, axis = a.ravel(), 0
    n = a.shape[axis]
    reps = [repeats] * n if isinstance(repeats, int) else list(repeats)
    idx = []
    for i, r in enumerate(reps):
        idx.extend([i] * int(r))
    return take(a, array(idx, dtype=int64), axis=axis)


def tile(A, reps):
    A = asarray(A)
    reps = (reps,) if isinstance(reps, int) else tuple(reps)
    nd = _builtins.max(len(reps), A.ndim)
    A = A.reshape((1,) * (nd - A.ndim) + A.shape)
    reps = (1,) * (nd - len(reps)) + reps
    for ax, r in enumerate(reps):
        if r != 1:
            A = concatenate([A] * r, axis=ax)
    return A


def flip(m, axis=None):
    m = asarray(m)
    axes = range(m.ndim) if axis is None else ([axis] if isinstance(axis, int) else axis)
    idx = [slice(None)] * m.ndim
    for ax in axes:
        idx[ax] = slice(None, None, -1)
    return m[tuple(idx)]


def fliplr(m):
    return flip(m, 1)


def flipud(m):
    return flip(m, 0)


def roll(a, shift, axis=None):
    a = asarray(a)
    if axis is None:
        return roll(a.ravel(), shift, 0).reshape(a.shape)
    n = a.shape[axis]
    if n == 0:
        return a.copy()
    k = shift % n
    return take(a, concatenate([arange(n - k, n), arange(0, n - k)]), axis=axis)


def rot90(m, k=1, axes=(0, 1)):
    m = asarray(m)
    k %= 4
    a0, a1 = axes
    if k == 0:
        return m.copy()
    if k == 2:
        return flip(flip(m, a0), a1)
    if k == 1:
        return swapaxes(flip(m, a1), a0, a1)
    return flip(swapaxes(m, a0, a1), a1)


def broadcast_to(array, shape, subok=False):
    return _np.broadcast_to(asarray(array), _shape(shape))


def broadcast_arrays(*args, subok=False):
    shape = broadcast_shapes(*[asarray(a).shape for a in args])
    return [broadcast_to(a, shape) for a in args]


def broadcast_shapes(*args):
    return _np.broadcast_shapes(*[_shape(s) for s in args])


def append(arr, values, axis=None):
    arr = asarray(arr)
    if axis is None:
        return concatenate([arr.ravel(), asarray(values).ravel()])
    return concatenate([arr, values], axis=axis)


def insert(arr, obj, values, axis=None):
    arr = asarray(arr)
    if axis is None:
        arr, axis = arr.ravel(), 0
    n = arr.shape[axis]
    i = obj if obj >= 0 else obj + n
    before = take(arr, arange(0, i), axis)
    after = take(arr, arange(i, n), axis)
    v = asarray(values, arr.dtype)
    if v.ndim < arr.ndim:
        s = list(arr.shape)
        s[axis] = 1 if v.ndim == 0 else v.shape[0]
        v = broadcast_to(v.reshape(s) if v.ndim else v, s)
    return concatenate([before, v, after], axis=axis)


def delete(arr, obj, axis=None):
    arr = asarray(arr)
    if axis is None:
        arr, axis = arr.ravel(), 0
    n = arr.shape[axis]
    drop = set(range(n)[obj]) if isinstance(obj, slice) else {int(i) % n for i in atleast_1d(asarray(obj)).tolist()}
    return take(arr, array([i for i in range(n) if i not in drop], dtype=int64), axis)


def resize(a, new_shape):
    a = asarray(a).ravel()
    shape = _shape(new_shape)
    n = 1
    for s in shape:
        n *= s
    if a.size == 0:
        return zeros(shape, a.dtype)
    reps = -(-n // a.size)
    return concatenate([a] * reps)[:n].reshape(shape)


def pad(array, pad_width, mode="constant", constant_values=0):
    a = asarray(array)
    pw = pad_width
    if isinstance(pw, int):
        pw = [(pw, pw)] * a.ndim
    elif isinstance(pw, (tuple, list)) and len(pw) == 2 and isinstance(pw[0], int):
        pw = [tuple(pw)] * a.ndim
    res = a
    for ax, (lo, hi) in enumerate(pw):
        if mode == "constant":
            parts = []
            s = list(res.shape)
            if lo:
                s[ax] = lo
                parts.append(full(s, constant_values, a.dtype))
            parts.append(res)
            if hi:
                s[ax] = hi
                parts.append(full(s, constant_values, a.dtype))
        elif mode == "edge":
            n = res.shape[ax]
            parts = [take(res, [0] * lo, ax), res, take(res, [n - 1] * hi, ax)]
        else:
            raise NotImplementedError("pad mode %r" % mode)
        res = concatenate(parts, axis=ax)
    return res


# ------------------------------------------------------------------ searching and sorting

def where(condition, x=None, y=None):
    if x is None and y is None:
        return nonzero(condition)
    if x is None or y is None:
        raise ValueError("either both or neither of x and y should be given")
    return _np.where3(asarray(condition, bool_), x, y)


def nonzero(a):
    return _np.nonzero(asarray(a))


def flatnonzero(a):
    return nonzero(ravel(a))[0]


def argwhere(a):
    nz = nonzero(a)
    return stack(nz, axis=1) if nz else zeros((0, 0), int64)


def sort(a, axis=-1, kind=None, order=None, *, stable=None):
    return _np.sort(asarray(a), axis)


def argsort(a, axis=-1, kind=None, order=None, *, stable=None):
    return _np.argsort(asarray(a), axis)


def lexsort(keys, axis=-1):
    keys = [asarray(k).tolist() for k in keys]
    n = len(keys[0])
    return array(sorted(range(n), key=lambda i: tuple(k[i] for k in reversed(keys))), dtype=int64)


def searchsorted(a, v, side="left", sorter=None):
    import bisect
    a = asarray(a).tolist()
    if sorter is not None:
        a = [a[i] for i in asarray(sorter).tolist()]
    f = bisect.bisect_left if side == "left" else bisect.bisect_right
    vv = asarray(v)
    res = [f(a, x) for x in vv.ravel().tolist()]
    return array(res, dtype=int64).reshape(vv.shape) if vv.ndim else int64(res[0])


def unique(ar, return_index=False, return_inverse=False, return_counts=False, axis=None, *, equal_nan=True):
    if not (return_index or return_inverse or return_counts) and asarray(ar).dtype.kind != "c":
        return _np.unique1d(ar)
    a = asarray(ar).ravel()
    order = argsort(a)
    s = a[order]
    if s.size == 0:
        flags = zeros(0, bool_)
    else:
        flags = concatenate([array([True]), s[1:] != s[:-1]])
        if s.dtype.kind in "fc" and equal_nan:
            nans = isnan(s)
            flags = flags & ~(nans & concatenate([array([False]), nans[:-1]]))
    u = s[flags]
    if not (return_index or return_inverse or return_counts):
        return u
    res = [u]
    starts = flatnonzero(flags)
    if return_index:
        res.append(order[starts])
    if return_inverse:
        inv = zeros(a.shape, int64)
        inv[order] = cumsum(flags) - 1
        res.append(inv.reshape(asarray(ar).shape))
    if return_counts:
        res.append(diff(concatenate([starts, array([s.size])])))
    return tuple(res)


def isin(element, test_elements, assume_unique=False, invert=False):
    e = asarray(element)
    t = set(asarray(test_elements).ravel().tolist())
    r = array([v in t for v in e.ravel().tolist()], dtype=bool_).reshape(e.shape)
    return ~r if invert else r


def _in1d(ar1, ar2, assume_unique=False, invert=False):
    # (NumPy 1.x's: the first argument flattened, a 1-D result)
    return isin(ravel(ar1), ar2, assume_unique=assume_unique, invert=invert)


in1d = _removed_alias(_in1d, "in1d", "np.isin")


def intersect1d(a, b, assume_unique=False):
    return unique(array(sorted(set(asarray(a).ravel().tolist()) & set(asarray(b).ravel().tolist())), dtype=result_type(asarray(a), asarray(b))))


def union1d(a, b):
    return unique(concatenate([asarray(a).ravel(), asarray(b).ravel()]))


def setdiff1d(a, b, assume_unique=False):
    bs = set(asarray(b).ravel().tolist())
    return unique(array([v for v in asarray(a).ravel().tolist() if v not in bs], dtype=asarray(a).dtype))


def diff(a, n=1, axis=-1, prepend=None, append=None):
    a = asarray(a)
    if prepend is not None or append is not None:
        parts = []
        for extra, first in ((prepend, True), (append, False)):
            if extra is None:
                continue
            p = asarray(extra)
            if p.ndim == 0:
                s = list(a.shape)
                s[axis] = 1
                p = broadcast_to(p, s)
            parts.append((first, p))
        a = concatenate([p for f, p in parts if f] + [a] + [p for f, p in parts if not f], axis=axis)
    for _ in range(n):
        lo = [slice(None)] * a.ndim
        hi = [slice(None)] * a.ndim
        lo[axis] = slice(None, -1)
        hi[axis] = slice(1, None)
        a = a[tuple(hi)] - a[tuple(lo)] if a.dtype.kind != "b" else not_equal(a[tuple(hi)], a[tuple(lo)])
    return a


def ediff1d(ary, to_end=None, to_begin=None):
    a = diff(asarray(ary).ravel())
    parts = ([asarray(to_begin).ravel()] if to_begin is not None else []) + [a] + ([asarray(to_end).ravel()] if to_end is not None else [])
    return concatenate(parts)


def gradient(f, *varargs, axis=None, edge_order=1):
    f = asarray(f, float64)
    axes = list(range(f.ndim)) if axis is None else ([axis] if isinstance(axis, int) else list(axis))
    # (NumPy's rule: no spacing, one scalar for every axis, or one per
    # axis; any other count is a TypeError, not a truncated zip)
    n = len(varargs)
    if n == 0:
        spacing = [1.0] * len(axes)
    elif n == 1 and ndim(varargs[0]) == 0:
        spacing = list(varargs) * len(axes)
    elif n == len(axes):
        spacing = list(varargs)
    else:
        raise TypeError("invalid number of arguments")
    if edge_order > 2:
        raise ValueError("'edge_order' greater than 2 not supported")
    if edge_order < 1:
        raise ValueError("'edge_order' must be 1 or 2")
    # (each spacing a scalar, or 1-D coordinates as long as its axis, as
    # NumPy's; evenly spaced coordinates are a scalar spacing, CORR-CDE-1)
    steps = []
    for ax, h in zip(axes, spacing):
        hv = asarray(h, float64)
        if hv.ndim == 0:
            steps.append(float(hv))
            continue
        if hv.ndim != 1:
            raise ValueError("distances must be either scalars or 1d")
        if len(hv) != f.shape[ax]:
            raise ValueError("when 1d, distances must match the length of the corresponding dimension")
        dx = diff(hv)
        steps.append(float(dx[0]) if len(dx) and bool((dx == dx[0]).all()) else dx)
    res = []
    for ax, h in zip(axes, steps):
        fm = moveaxis(f, ax, 0)
        if fm.shape[0] < edge_order + 1:
            raise ValueError("Shape of array too small to calculate a numerical gradient, at least (edge_order + 1) elements are required.")
        g = zeros(fm.shape, float64)
        if not isinstance(h, ndarray):
            g[1:-1] = (fm[2:] - fm[:-2]) / (2 * h)
            if edge_order == 1:
                g[0] = (fm[1] - fm[0]) / h
                g[-1] = (fm[-1] - fm[-2]) / h
            else:
                g[0] = (-1.5 * fm[0] + 2.0 * fm[1] - 0.5 * fm[2]) / h
                g[-1] = (0.5 * fm[-3] - 2.0 * fm[-2] + 1.5 * fm[-1]) / h
        else:
            dx = h
            dx1, dx2 = dx[:-1], dx[1:]
            a = -dx2 / (dx1 * (dx1 + dx2))
            b = (dx2 - dx1) / (dx1 * dx2)
            c = dx1 / (dx2 * (dx1 + dx2))
            sh = (-1,) + (1,) * (fm.ndim - 1)
            g[1:-1] = a.reshape(sh) * fm[:-2] + b.reshape(sh) * fm[1:-1] + c.reshape(sh) * fm[2:]
            if edge_order == 1:
                g[0] = (fm[1] - fm[0]) / dx[0]
                g[-1] = (fm[-1] - fm[-2]) / dx[-1]
            else:
                d1, d2 = float(dx[0]), float(dx[1])
                g[0] = (-(2.0 * d1 + d2) / (d1 * (d1 + d2))) * fm[0] + ((d1 + d2) / (d1 * d2)) * fm[1] + (-d1 / (d2 * (d1 + d2))) * fm[2]
                d1, d2 = float(dx[-2]), float(dx[-1])
                g[-1] = (d2 / (d1 * (d1 + d2))) * fm[-3] + (-(d2 + d1) / (d1 * d2)) * fm[-2] + ((2.0 * d2 + d1) / (d2 * (d1 + d2))) * fm[-1]
        res.append(moveaxis(g, 0, ax))
    return res[0] if len(res) == 1 else res


def trapezoid(y, x=None, dx=1.0, axis=-1):
    y = asarray(y)
    n = y.shape[axis]
    lo = [slice(None)] * y.ndim
    hi = [slice(None)] * y.ndim
    lo[axis] = slice(None, -1)
    hi[axis] = slice(1, None)
    if x is None:
        d = dx
    else:
        x = asarray(x)
        d = diff(x) if x.ndim == 1 else diff(x, axis=axis)
        if x.ndim == 1 and y.ndim > 1:
            s = [1] * y.ndim
            s[axis] = n - 1
            d = d.reshape(s)
    return sum(d * (y[tuple(hi)] + y[tuple(lo)]) / 2.0, axis=axis)


trapz = _removed_alias(trapezoid, "trapz", "np.trapezoid")


def cross(a, b, axisa=-1, axisb=-1, axisc=-1, axis=None):
    a, b = asarray(a), asarray(b)
    if a.shape[-1] == 2 and b.shape[-1] == 2:
        return a[..., 0] * b[..., 1] - a[..., 1] * b[..., 0]
    a0, a1, a2 = a[..., 0], a[..., 1], a[..., 2]
    b0, b1, b2 = b[..., 0], b[..., 1], b[..., 2]
    return stack([a1 * b2 - a2 * b1, a2 * b0 - a0 * b2, a0 * b1 - a1 * b0], axis=-1)


def interp(x, xp, fp, left=None, right=None, period=None):
    import bisect
    xp_l = asarray(xp, float64).tolist()
    fp_a = asarray(fp)
    cplx = fp_a.dtype.kind == "c"
    fp_l = fp_a.tolist()
    xs = asarray(x, float64)
    if period is not None:
        # (NumPy's: x and xp taken modulo the period, xp sorted, and one
        # period's continuation each side; left and right are not used)
        period = float(period)
        if period == 0:
            raise ValueError("period must be a non-zero value")
        # (NumPy's answers for an infinite or nan period come from its own
        # arithmetic on them; refused rather than guessed, CORR-928-1)
        if period != period or period in (float("inf"), float("-inf")):
            raise NotImplementedError("numpy.interp with a period that is not finite is not supported in Sagebrush")
        period = abs(period)
        if len(xp_l) != len(fp_l):
            raise ValueError("fp and xp are not of the same length")
        pairs = sorted(zip([v % period for v in xp_l], fp_l), key=lambda t: t[0])
        xp_l = [pairs[-1][0] - period] + [p[0] for p in pairs] + [pairs[0][0] + period]
        fp_l = [pairs[-1][1]] + [p[1] for p in pairs] + [pairs[0][1]]
        xs = asarray(xs % period, float64)
        left = right = None
    lo_v = fp_l[0] if left is None else left
    hi_v = fp_l[-1] if right is None else right
    res = []
    n = len(xp_l)
    for v in xs.ravel().tolist():
        if v != v:
            res.append(nan)
        elif v < xp_l[0]:
            res.append(lo_v)
        elif v > xp_l[-1]:
            res.append(hi_v)
        else:
            j = bisect.bisect_right(xp_l, v) - 1
            if j >= n - 1:
                res.append(fp_l[-1])
            else:
                slope = (fp_l[j + 1] - fp_l[j]) / (xp_l[j + 1] - xp_l[j])
                res.append(slope * (v - xp_l[j]) + fp_l[j])
    r = array(res, dtype=complex128 if cplx else float64).reshape(xs.shape)
    return r if r.ndim else r[()]


def convolve(a, v, mode="full"):
    a, v = asarray(a).ravel(), asarray(v).ravel()
    if a.size < v.size:
        a, v = v, a
    n, m = a.size, v.size
    av, vv = a.tolist(), v.tolist()
    full_ = [0] * (n + m - 1)
    for i in range(n):
        ai = av[i]
        for j in range(m):
            full_[i + j] += ai * vv[j]
    r = array(full_, dtype=result_type(a, v))
    if mode == "full":
        return r
    if mode == "same":
        start = (m - 1) // 2
        return r[start:start + n]
    if mode == "valid":
        return r[m - 1:n]
    raise ValueError("mode must be 'full', 'same' or 'valid'")


def correlate(a, v, mode="valid"):
    return convolve(a, asarray(v)[::-1].conj(), mode)


def histogram(a, bins=10, range=None, density=None, weights=None):
    import bisect
    a = asarray(a).ravel()
    if isinstance(bins, int):
        if range is None:
            lo, hi = (float(amin(a)), float(amax(a))) if a.size else (0.0, 1.0)
        else:
            lo, hi = float(range[0]), float(range[1])
        if lo == hi:
            lo, hi = lo - 0.5, hi + 0.5
        edges = linspace(lo, hi, bins + 1)
    else:
        edges = asarray(bins, float64)
    nb = edges.size - 1
    if isinstance(bins, int) and weights is None:
        hist = _np.hist_uniform(a, edges[0], edges[-1], nb, edges)
        if density:
            hist = hist / diff(edges) / sum(hist)
        return hist, edges
    e = edges.tolist()
    counts = [0] * nb
    w = asarray(weights).ravel().tolist() if weights is not None else None
    lo, hi = e[0], e[-1]
    uniform = isinstance(bins, int)
    for i, v in enumerate(a.tolist()):
        if v < lo or v > hi or v != v:
            continue
        if uniform:
            k = int((v - lo) / (hi - lo) * nb)
            if k >= nb:
                k = nb - 1
            if v < e[k]:
                k -= 1
            elif k < nb - 1 and v >= e[k + 1]:
                k += 1
        else:
            k = bisect.bisect_right(e, v) - 1
            if k == nb:
                k = nb - 1
        counts[k] += w[i] if w is not None else 1
    hist = array(counts, dtype=float64 if (weights is not None and asarray(weights).dtype.kind == "f") else int64)
    if density:
        hist = hist / diff(edges) / sum(hist)
    return hist, edges


def histogram_bin_edges(a, bins=10, range=None, weights=None):
    return histogram(a, bins, range)[1]


def bincount(x, weights=None, minlength=0):
    xs = asarray(x).tolist()
    n = _builtins.max((_builtins.max(xs) + 1) if xs else 0, minlength)
    if weights is None:
        res = [0] * n
        for v in xs:
            res[v] += 1
        return array(res, dtype=int64)
    w = asarray(weights).tolist()
    res = [0.0] * n
    for v, wt in zip(xs, w):
        res[v] += wt
    return array(res)


def digitize(x, bins, right=False):
    b = asarray(bins).tolist()
    increasing = len(b) < 2 or b[1] >= b[0]
    side = "left" if right else "right"
    if increasing:
        return searchsorted(b, x, side=side)
    return len(b) - searchsorted(b[::-1], x, side="left" if side == "right" else "right")


# ------------------------------------------------------------------ products

def dot(a, b, out=None):
    a, b = asarray(a), asarray(b)
    if a.ndim == 0 or b.ndim == 0:
        r = multiply(a, b)
        return _out(r if r.ndim else r[()], out)
    if b.ndim > 2:
        return _out(tensordot(a, b, axes=([a.ndim - 1], [b.ndim - 2])), out)
    return _out(_np.matmul(a, b), out)


def matmul(a, b, out=None):
    return _out(_np.matmul(asarray(a), asarray(b)), out)


def vdot(a, b):
    return dot(asarray(a).ravel().conj(), asarray(b).ravel())


def inner(a, b):
    a, b = asarray(a), asarray(b)
    if a.ndim == 0 or b.ndim == 0:
        return a * b
    return tensordot(a, b, axes=([a.ndim - 1], [b.ndim - 1]))


def outer(a, b, out=None):
    a, b = asarray(a).ravel(), asarray(b).ravel()
    return _out(multiply(a[:, None], b[None, :]), out)


def tensordot(a, b, axes=2):
    a, b = asarray(a), asarray(b)
    if isinstance(axes, int):
        axa = list(range(a.ndim - axes, a.ndim))
        axb = list(range(axes))
    else:
        axa, axb = axes
        axa = [axa] if isinstance(axa, int) else list(axa)
        axb = [axb] if isinstance(axb, int) else list(axb)
    axa = [x % a.ndim for x in axa]
    axb = [x % b.ndim for x in axb]
    fa = [i for i in range(a.ndim) if i not in axa]
    fb = [i for i in range(b.ndim) if i not in axb]
    k = 1
    for x in axa:
        k *= a.shape[x]
    A = transpose(a, fa + axa).reshape(-1, k)
    B = transpose(b, axb + fb).reshape(k, -1)
    r = asarray(A @ B).reshape(tuple(a.shape[i] for i in fa) + tuple(b.shape[i] for i in fb))
    return r if r.ndim else r[()]


def einsum(subscripts, *operands, optimize=False):
    ops = [asarray(o) for o in operands]
    subscripts = subscripts.replace(" ", "")
    if "->" in subscripts:
        ins, out = subscripts.split("->")
    else:
        ins = subscripts
        letters = "".join(ins.split(","))
        out = "".join(sorted(c for c in set(letters) if letters.count(c) == 1))
    ins = ins.split(",")
    dims = {}
    for spec, op in zip(ins, ops):
        if len(set(spec)) != len(spec):
            # a repeated index in one operand: take the diagonal
            raise NotImplementedError("einsum with a repeated index in one operand")
        for c, n in zip(spec, op.shape):
            dims[c] = n
    letters = sorted(dims)
    acc = None
    for spec, op in zip(ins, ops):
        o = transpose(op, [spec.index(c) for c in letters if c in spec])
        o = o.reshape([dims[c] if c in spec else 1 for c in letters])
        acc = o if acc is None else acc * o
    summed = tuple(i for i, c in enumerate(letters) if c not in out)
    r = asarray(sum(acc, axis=summed) if summed else acc)
    remaining = [c for c in letters if c in out]
    if remaining:
        r = transpose(r, [remaining.index(c) for c in out])
    return r if r.ndim else r[()]


def kron(a, b):
    a, b = asarray(a), asarray(b)
    if a.ndim == 1 and b.ndim == 1:
        return outer(a, b).ravel()
    a2, b2 = atleast_2d(a), atleast_2d(b)
    r = a2[:, None, :, None] * b2[None, :, None, :]
    return r.reshape(a2.shape[0] * b2.shape[0], a2.shape[1] * b2.shape[1])


def trace(a, offset=0, axis1=0, axis2=1, dtype=None, out=None):
    return sum(diagonal(asarray(a), offset))


# ------------------------------------------------------------------ comparisons and helpers

def isclose(a, b, rtol=1e-05, atol=1e-08, equal_nan=False):
    a, b = asarray(a), asarray(b)
    r = logical_or(less_equal(absolute(a - b), atol + rtol * absolute(b)), equal(a, b))
    if equal_nan:
        r = logical_or(r, logical_and(isnan(a), isnan(b)))
    return r if r.ndim else r[()]


def allclose(a, b, rtol=1e-05, atol=1e-08, equal_nan=False):
    return _builtins.bool(all(isclose(a, b, rtol, atol, equal_nan)))


def array_equal(a1, a2, equal_nan=False):
    a1, a2 = asarray(a1), asarray(a2)
    if a1.shape != a2.shape:
        return False
    if equal_nan:
        return _builtins.bool(all((a1 == a2) | (isnan(a1) & isnan(a2))))
    return _builtins.bool(all(a1 == a2))


def array_equiv(a1, a2):
    try:
        return _builtins.bool(all(asarray(a1) == asarray(a2)))
    except ValueError:
        return False


def apply_along_axis(func1d, axis, arr, *args, **kwargs):
    arr = asarray(arr)
    a = moveaxis(arr, axis, -1)
    outer_shape = a.shape[:-1]
    flat = a.reshape(-1, a.shape[-1])
    res = array([asarray(func1d(flat[i], *args, **kwargs)) for i in range(flat.shape[0])])
    res = res.reshape(outer_shape + res.shape[1:])
    if res.ndim > len(outer_shape):
        res = moveaxis(res, -1, axis)
    return res


def vectorize(pyfunc, otypes=None, excluded=None, signature=None):
    def f(*args):
        arrs = broadcast_arrays(*[asarray(a) for a in args])
        flat = [a.ravel().tolist() for a in arrs]
        res = [pyfunc(*vals) for vals in zip(*flat)]
        r = array(res, dtype=otypes[0] if otypes else None) if res else zeros(0)
        r = r.reshape(arrs[0].shape) if arrs else r
        return r if r.ndim else r[()]
    return f


def piecewise(x, condlist, funclist, *args, **kw):
    x = asarray(x)
    res = zeros(x.shape, x.dtype)  # (x's dtype, as NumPy's: values are cast to it)
    condlist = [asarray(c, bool_) for c in (condlist if isinstance(condlist, list) else [condlist])]
    if len(funclist) == len(condlist) + 1:
        rest = ones(x.shape, bool_)
        for c in condlist:
            rest = rest & ~c
        condlist.append(rest)
    for c, f in zip(condlist, funclist):
        res[c] = f(x[c], *args, **kw) if callable(f) else f
    return res


def select(condlist, choicelist, default=0):
    res = asarray(default)
    for c, v in reversed(list(zip(condlist, choicelist))):
        res = where(c, v, res)
    return res


class errstate:
    def __init__(self, **kw):
        pass

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        return False

    def __call__(self, f):
        return f


def seterr(**kw):
    return geterr()


def geterr():
    return {"divide": "warn", "over": "warn", "under": "ignore", "invalid": "warn"}


# ------------------------------------------------------------------ printing

def _index(v):
    """operator.index, with CPython's TypeError"""
    from _operator import index
    return index(v)


def _c_int(v):
    """v as NumPy's C code takes an int argument: an index, which must fit a C int."""
    if isinstance(v, float):
        raise TypeError("integer argument expected, got float")
    v = _index(v)
    if not -2 ** 63 <= v < 2 ** 63:
        raise OverflowError("Python int too large to convert to C long")
    if not -2 ** 31 <= v < 2 ** 31:
        raise OverflowError("Python int too large to convert to C int")
    return v


_PRINT_DEFAULTS = {"edgeitems": 3, "threshold": 1000, "floatmode": "maxprec", "precision": 8, "suppress": False,
                   "linewidth": 75, "nanstr": "nan", "infstr": "inf", "sign": "-", "formatter": None,
                   "legacy": False, "override_repr": None}
_printopts = dict(_PRINT_DEFAULTS)
_FLOATMODES = ("fixed", "unique", "maxprec", "maxprec_equal")


def _formatter_functions(formatter):
    """formatter's functions for the kinds Sagebrush's arrays have: (bool,
    int, float, complex), by NumPy's precedence ('all', then the *_kind
    groups, then the type's own key); keys for other kinds do nothing, as in
    NumPy."""
    out = {"bool": None, "int": None, "float": None, "complexfloat": None}
    if not formatter:
        return out
    f = {k: v for k, v in formatter.items() if v is not None}
    if "all" in f:
        for k in out:
            out[k] = f["all"]
    for group, keys in (("int_kind", ["int"]), ("float_kind", ["float"]), ("complex_kind", ["complexfloat"])):
        if group in f:
            for k in keys:
                out[k] = f[group]
    for k in out:
        if k in f:
            out[k] = f[k]
    return out


def _push_printoptions():
    o = _printopts
    fs = _formatter_functions(o["formatter"])
    # Dragon4 takes the precision as a C int: one too large for that is an
    # error once floats are printed (the TS printer raises for 2**31 or 2**63)
    p = o["precision"]
    if p >= 2 ** 31:
        p = 2 ** 63 if p >= 2 ** 63 else 2 ** 31
    _np.set_printoptions(p, o["threshold"], o["edgeitems"], o["linewidth"], o["suppress"], o["sign"],
                         o["floatmode"], o["nanstr"], o["infstr"], fs["bool"], fs["int"], fs["float"],
                         fs["complexfloat"], o["override_repr"])


def _checked_printoptions(precision=None, threshold=None, edgeitems=None, linewidth=None, suppress=None,
                          nanstr=None, infstr=None, formatter=None, sign=None, floatmode=None, legacy=None,
                          override_repr=None):
    """The options after these changes (None: unchanged), validated as NumPy does."""
    new = dict(_printopts)
    if legacy is not None and legacy is not False:
        raise NotImplementedError("legacy=%r (NumPy's older printing) is not implemented in Sagebrush" % (legacy,))
    if precision is not None:
        try:
            precision = _index(precision)
        except TypeError:
            raise TypeError("precision must be an integer") from None
        if precision < 0:
            raise ValueError("precision must be >= 0")
        new["precision"] = precision
    if threshold is not None:
        if not isinstance(threshold, (int, float)) or isinstance(threshold, bool):
            raise TypeError("threshold must be numeric")
        if isinstance(threshold, int) and not -2 ** 63 <= threshold < 2 ** 64:
            # NumPy's np.isnan(threshold) on an int that only fits an object array
            raise TypeError("ufunc 'isnan' not supported for the input types, and the inputs could not be safely coerced "
                            "to any supported types according to the casting rule ''safe''")
        if threshold != threshold:
            raise ValueError("threshold must be non-NAN, try sys.maxsize for untruncated representation")
        new["threshold"] = threshold
    for name, v in (("edgeitems", edgeitems), ("linewidth", linewidth)):
        if v is not None:
            new[name] = _index(v)
    if suppress is not None:
        new["suppress"] = _builtins.bool(suppress)
    for name, v in (("nanstr", nanstr), ("infstr", infstr)):
        if v is not None:
            if not isinstance(v, str):
                raise TypeError("%s must be a string" % name)
            new[name] = v
    if sign is not None:
        if sign not in ("-", "+", " "):
            raise ValueError("sign option must be one of ' ', '+', or '-'")
        new["sign"] = sign
    if floatmode is not None:
        if floatmode not in _FLOATMODES:
            raise ValueError('floatmode option must be one of "fixed", "unique", "maxprec", "maxprec_equal"')
        new["floatmode"] = floatmode
    if formatter is not None:
        if not isinstance(formatter, dict):
            raise TypeError("formatter must be a dict")
        for k, v in formatter.items():
            if v is not None and not callable(v):
                raise TypeError("formatter[%r] must be callable" % (k,))
    # (formatter and override_repr: None resets them, as in NumPy)
    new["formatter"] = formatter
    if override_repr is not None and not callable(override_repr):
        raise TypeError("override_repr must be callable")
    new["override_repr"] = override_repr
    return new


def set_printoptions(precision=None, threshold=None, edgeitems=None, linewidth=None, suppress=None,
                     nanstr=None, infstr=None, formatter=None, sign=None, floatmode=None, *, legacy=None,
                     override_repr=None):
    """How arrays print (NumPy's options; legacy is not implemented)."""
    global _printopts
    _printopts = _checked_printoptions(precision, threshold, edgeitems, linewidth, suppress, nanstr, infstr,
                                       formatter, sign, floatmode, legacy, override_repr)
    _push_printoptions()


def get_printoptions():
    return dict(_printopts)


class printoptions:
    """with np.printoptions(...) as opts: the options inside the block only."""

    def __init__(self, *args, **kw):
        self.args, self.kw = args, kw

    def __enter__(self):
        global _printopts
        self.saved = dict(_printopts)
        set_printoptions(*self.args, **self.kw)
        return get_printoptions()

    def __exit__(self, *exc):
        global _printopts
        _printopts = self.saved
        _push_printoptions()
        return False


def array2string(a, max_line_width=None, precision=None, suppress_small=None, separator=" ", prefix="",
                 formatter=None, threshold=None, edgeitems=None, sign=None, floatmode=None, suffix="", *,
                 legacy=None):
    """The text of an array's elements, NumPy's way, with these options for it only."""
    with printoptions(precision=precision, threshold=threshold, edgeitems=edgeitems, linewidth=max_line_width,
                      suppress=suppress_small, formatter=formatter if formatter is not None else _printopts["formatter"],
                      sign=sign, floatmode=floatmode, legacy=legacy,
                      override_repr=_printopts["override_repr"]):
        return _np.array_text(asarray(a), separator, prefix, suffix)


def array_repr(arr, max_line_width=None, precision=None, suppress_small=None):
    with printoptions(precision=precision, linewidth=max_line_width, suppress=suppress_small,
                      formatter=_printopts["formatter"], override_repr=_printopts["override_repr"]):
        return _np.array_repr(asarray(arr))


def array_str(a, max_line_width=None, precision=None, suppress_small=None):
    with printoptions(precision=precision, linewidth=max_line_width, suppress=suppress_small,
                      formatter=_printopts["formatter"], override_repr=_printopts["override_repr"]):
        return _np.array_str(asarray(a))


_TRIMS = ("k", ".", "0", "-")


def _none_or_positive_arg(x, name):
    if x is None:
        return -1
    if x < 0:
        raise ValueError("%s must be >= 0" % name)
    return x


def _dragon4_value(x):
    """x as NumPy's Dragon4 entry points take it: a float32 scalar keeps its
    own shortest digits; anything else becomes a float (a complex scalar its
    real part, which NumPy does with a ComplexWarning Sagebrush does not have)."""
    if isinstance(x, generic):
        if isinstance(x, complexfloating):
            return float(float32(x.real)) if isinstance(x, complex64) else float(x.real), False
        return float(x), isinstance(x, float32)
    if isinstance(x, ndarray):
        if x.ndim:
            raise TypeError("only 0-dimensional arrays can be converted to Python scalars")
        return float(x[()]), False
    if isinstance(x, (str, bytes, complex)) or not (hasattr(type(x), "__float__") or hasattr(type(x), "__index__")):
        raise TypeError("must be real number, not %s" % type(x).__name__)
    return float(x), False


def _dragon4_args(x, args):
    """The conversions NumPy's C entry points make, in their argument order:
    each flag and size a C int (sizes are -1 for None), trim one of _TRIMS;
    then precision is needed in non-unique mode.  Returns the float, whether
    it is a float32, and the arguments (sizes None for -1, flags as bools)."""
    out = {}
    for name, v in args:
        if name == "trim":
            if v not in _TRIMS:
                raise TypeError("if supplied, trim must be 'k', '.', '0' or '-' found `%100s`" % (v,))
            out[name] = v
        elif name in ("unique", "fractional", "sign"):
            out[name] = _builtins.bool(_c_int(v))
        else:
            v = _c_int(v)
            out[name] = None if v == -1 else v
    if not out["unique"] and out["precision"] is None:
        raise TypeError("in non-unique mode `precision` must be supplied")
    v, f32 = _dragon4_value(x)
    return v, f32, out


def format_float_positional(x, precision=None, unique=True, fractional=True, trim="k", sign=False,
                            pad_left=None, pad_right=None, min_digits=None):
    """A float in positional notation: NumPy's Dragon4 (shortest unique
    digits, or exactly rounded ones, half to even)."""
    precision = _none_or_positive_arg(precision, "precision")
    pad_left = _none_or_positive_arg(pad_left, "pad_left")
    pad_right = _none_or_positive_arg(pad_right, "pad_right")
    min_digits = _none_or_positive_arg(min_digits, "min_digits")
    if not fractional and precision == 0:
        raise ValueError("precision must be greater than 0 if fractional=False")
    if min_digits > 0 and precision > 0 and min_digits > precision:
        raise ValueError("min_digits must be less than or equal to precision")
    v, f32, o = _dragon4_args(x, [("precision", precision), ("unique", unique), ("fractional", fractional), ("trim", trim),
                                  ("sign", sign), ("pad_left", pad_left), ("pad_right", pad_right), ("min_digits", min_digits)])
    return _np.format_float_positional(v, o["precision"], o["unique"], o["fractional"], trim, o["sign"], o["pad_left"],
                                       o["pad_right"], o["min_digits"], f32)


def format_float_scientific(x, precision=None, unique=True, trim="k", sign=False, pad_left=None,
                            exp_digits=None, min_digits=None):
    """A float in scientific notation: NumPy's Dragon4."""
    precision = _none_or_positive_arg(precision, "precision")
    pad_left = _none_or_positive_arg(pad_left, "pad_left")
    exp_digits = _none_or_positive_arg(exp_digits, "exp_digits")
    min_digits = _none_or_positive_arg(min_digits, "min_digits")
    if min_digits > 0 and precision > 0 and min_digits > precision:
        raise ValueError("min_digits must be less than or equal to precision")
    v, f32, o = _dragon4_args(x, [("precision", precision), ("unique", unique), ("trim", trim), ("sign", sign),
                                  ("pad_left", pad_left), ("exp_digits", exp_digits), ("min_digits", min_digits)])
    return _np.format_float_scientific(v, o["precision"], o["unique"], trim, o["sign"], o["pad_left"], o["exp_digits"],
                                       o["min_digits"], f32)


def isscalar(element):
    """Whether element is a scalar: a NumPy scalar, or a Python number, str,
    bytes or memoryview (not a 0-d array)."""
    import numbers
    if element is None or isinstance(element, ndarray):
        return False
    return (isinstance(element, generic) or isinstance(element, (int, float, complex, bool, str, bytes, memoryview))
            or isinstance(element, numbers.Number))


def _nextafter32(a, b):
    import struct
    if a != a or b != b:
        return float("nan")
    if a == b:
        return b
    if a == 0.0:
        tiny = struct.unpack("<f", struct.pack("<I", 1))[0]
        return tiny if b > 0 else -tiny
    i = struct.unpack("<I", struct.pack("<f", a))[0]
    i = i + 1 if (b > a) == (a > 0) else i - 1
    return struct.unpack("<f", struct.pack("<I", i))[0]


_NEXTAFTER_UNSUPPORTED = ("ufunc 'nextafter' not supported for the input types, and the inputs could not be safely "
                          "coerced to any supported types according to the casting rule ''safe''")


def _nextafter_dtype(x1, x2):
    """NumPy 2's loop for nextafter: the first of float16, float32 and float64
    that both operands cast to safely, a Python int, float or complex being
    weak (NEP 50): an int counts as the other operand's type (int64 for a
    bool), a float as the other's if that is a float, else float64."""
    def weak(x):
        if isinstance(x, (ndarray, generic)) or isinstance(x, _builtins.bool):
            return None
        return "i" if isinstance(x, int) else "f" if isinstance(x, float) else "c" if isinstance(x, complex) else None
    w1, w2 = weak(x1), weak(x2)
    if "c" in (w1, w2):
        raise TypeError(_NEXTAFTER_UNSUPPORTED)
    if w1 and w2:
        kinds = [dtype(int64) if w == "i" else dtype(float64) for w in (w1, w2)]
    elif w1 or w2:
        w, strong = (w1, x2) if w1 else (w2, x1)
        s = asarray(strong).dtype
        if w == "i":
            t = dtype(int64) if s.kind == "b" else s
        else:
            t = s if s.kind == "f" else dtype(float64)
        kinds = [s, t]
    else:
        kinds = [asarray(x1).dtype, asarray(x2).dtype]
    if _builtins.any(k.kind == "c" for k in kinds):
        raise TypeError(_NEXTAFTER_UNSUPPORTED)
    if _builtins.all(k.kind == "b" or (k.kind in "iu" and k.itemsize == 1) for k in kinds):
        raise NotImplementedError("nextafter: NumPy computes this in float16 (for bool, int8 and uint8 inputs), "
                                  "which Sagebrush does not have")
    if _builtins.all(k == float32 or k.kind == "b" or (k.kind in "iu" and k.itemsize <= 2) for k in kinds):
        return dtype(float32)
    return dtype(float64)


def nextafter(x1, x2, out=None, **kw):
    """The next floating-point value after x1 towards x2, elementwise, in
    NumPy 2's dtype (float32 for float32 with a Python float, for instance)."""
    if kw:
        raise NotImplementedError("nextafter: %s are not implemented in Sagebrush" % ", ".join(sorted(kw)))
    dt = _nextafter_dtype(x1, x2)
    # a weak Python int goes straight to the loop's type (70000 with an int16)
    a, b = (asarray(float(x) if isinstance(x, int) and not isinstance(x, _builtins.bool) else x).astype(dt) for x in (x1, x2))
    a, b = broadcast_arrays(a, b)
    step = _nextafter32 if dt == float32 else _math.nextafter
    vals = [step(p, q) for p, q in zip(a.ravel().tolist(), b.ravel().tolist())]
    res = array(vals, dtype=dt).reshape(a.shape)
    return _out(res[()] if res.ndim == 0 else res, out)


