        q, r = polydiv(self.coeffs, self._other(o))
        return poly1d(q), poly1d(r)

    def deriv(self, m=1):
        return poly1d(polyder(self.coeffs, m))

    def integ(self, m=1, k=0):
        return poly1d(polyint(self.coeffs, m, k))


