            seed = [int.from_bytes(os.urandom(4), "little") for _ in range(8)]
        if isinstance(seed, (list, tuple, _np.ndarray)):
            self._g = _r.mt19937([int(s) for s in _np.asarray(seed).ravel().tolist()])
        else:
