        raise NotImplementedError("only dtype=float64 is implemented for this distribution")
    if out is None:
        return r
    if out.dtype != _np.float64:
        raise TypeError("Supplied output array has the wrong type. Expected float64, got %s" % out.dtype)
    out[...] = r
    return out


